/**
 * Calls to the API, typed from its OpenAPI description (`schema.ts`, generated by `just openapi`).
 * In the browser, `/api` is the site itself, which relays to the API: same origin, first-party
 * cookies. On the server, the call goes straight to the API, with the visitor's cookies.
 */
import type { components, paths } from "./schema";

export type Schemas = components["schemas"];
export type Me = Schemas["Me"];

type JsonOf<Operation> = Operation extends {
  responses: { 200: { content: { "application/json": infer Body } } };
}
  ? Body
  : never;

/** The paths that answer a GET with a JSON body. */
export type GetPath = {
  [P in keyof paths]: paths[P] extends { get: infer Operation }
    ? JsonOf<Operation> extends never
      ? never
      : P
    : never;
}[keyof paths];

export type GetResult<P extends GetPath> = paths[P] extends { get: infer Operation }
  ? JsonOf<Operation>
  : never;

export class ApiError extends Error {
  constructor(
    readonly status: number,
    readonly code: string,
  ) {
    super(code);
  }
}

/** Fills `{name}` in a path from `parameters`, encoded. */
export function fillPath(path: string, parameters: Record<string, string> = {}): string {
  return path.replace(/\{(\w+)\}/g, (_, name: string) => {
    const value = parameters[name];
    if (value === undefined) throw new Error(`missing path parameter: ${name}`);
    return encodeURIComponent(value);
  });
}

export async function getJson<P extends GetPath>(
  path: P,
  options: { base?: string; parameters?: Record<string, string>; init?: RequestInit } = {},
): Promise<GetResult<P>> {
  const response = await fetch(`${options.base ?? ""}${fillPath(path, options.parameters)}`, {
    ...options.init,
    headers: { Accept: "application/json", ...options.init?.headers },
  });
  if (!response.ok) {
    const body: unknown = await response.json().catch(() => null);
    const code =
      typeof body === "object" && body !== null && "error" in body
        ? String((body as { error: { code?: unknown } }).error.code ?? "internal")
        : "internal";
    throw new ApiError(response.status, code);
  }
  return (await response.json()) as GetResult<P>;
}
